{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://goobers.dev/schemas/workflow.schema.json",
  "title": "Workflow",
  "description": "A process modeled as a deterministic state machine of Tasks and Gates (WF-001..024).",
  "type": "object",
  "additionalProperties": false,
  "required": ["apiVersion", "kind", "metadata", "spec"],
  "properties": {
    "apiVersion": { "const": "goobers.dev/v1alpha1", "description": "API version of this workflow definition." },
    "kind": { "const": "Workflow", "description": "Definition kind; always Workflow." },
    "dslVersion": { "type": "string", "pattern": "^[0-9]+\\.[0-9]+$", "examples": ["1.4"], "description": "Workflow DSL version in major.minor form. Omit to use the current supported version." },
    "metadata": { "$ref": "#/$defs/metadata", "description": "Identity and optional labels or annotations for this workflow." },
    "spec": {
      "type": "object",
      "description": "The workflow's triggers, run controls, and deterministic state-machine definition.",
      "additionalProperties": false,
      "required": ["gaggle", "triggers", "start"],
      "properties": {
        "gaggle": { "type": "string", "minLength": 1, "examples": ["example"], "description": "Name of the gaggle this workflow belongs to." },
        "displayName": { "type": "string", "description": "Human-facing workflow name shown in the portal." },
        "enabled": {
          "type": ["boolean", "null"],
          "description": "Selects whether new runs may start for this workflow. Defaults to true; null or omitted means true (enabled). Setting false disables new run starts for this workflow without changing its schedule or backlog configuration."
        },
        "triggers": {
          "type": "array",
          "description": "Conditions that may start a run once readiness checks also pass. A manual trigger must be the only trigger.",
          "minItems": 1,
          "items": { "$ref": "#/$defs/trigger" },
          "allOf": [
            {
              "if": {
                "contains": {
                  "type": "object",
                  "required": ["type"],
                  "properties": { "type": { "const": "manual" } }
                }
              },
              "then": { "maxItems": 1 }
            }
          ]
        },
        "scheduleCatchUp": {
          "type": "string",
          "enum": ["coalesce", "all"],
          "description": "Missed schedule policy. Omitted or coalesce captures one firing from the preceding hour. All durably retains each nominal occurrence, discovering at most 100 per sweep with normal admission and idle backoff. Requires 1..1000 schedule declarations. Does not promise execution ordering."
        },
        "readiness": {
          "type": "object",
          "description": "Admission limits that bound when runs may start. maxChainDepth is reserved and is not currently enforced.",
          "additionalProperties": false,
          "properties": {
            "claimVisibility": { "type": "string", "enum": ["local", "shared"], "description": "Claim coordination mode. Omitted or local uses instance-local claims. Shared additionally requires a provider-backed lease; GitHub is supported and unsupported providers fail closed." },
            "desiredConcurrentRuns": { "type": "integer", "minimum": 1, "description": "Opt-in target occupancy for eligible queue work. Refill remains subject to every admission limit and never exceeds maxConcurrentRuns." },
            "maxConcurrentRuns": { "type": "integer", "minimum": 1, "description": "Maximum simultaneous runs of this workflow." },
            "maxRunsPerHour": { "type": "integer", "minimum": 0, "description": "Rolling hourly run budget. An operator may explicitly bypass the ceiling for one manual invocation with `goobers run --force`. Zero or omitted both fall back to the scheduler default of 10 — NOT unlimited (that is instance.yaml's runConditions.maxParallelRuns, where zero does mean unlimited). Set an explicit large value if you want a high hourly ceiling." },
            "maxRunsPerDay": { "type": "integer", "minimum": 0, "description": "Rolling 24-hour run budget. An operator may explicitly bypass the ceiling for one manual invocation with `goobers run --force`. Zero or omitted disables the daily cap." },
            "maxChainDepth": { "type": "integer", "minimum": 0, "description": "Reserved maximum depth for signal-triggered workflow chains. The scheduler does not currently enforce this field, and configuring it has no effect." },
            "maxOpenPRs": { "type": "integer", "minimum": 0, "description": "Maximum open pull requests produced by this workflow. Zero or omitted disables the cap." },
            "requireProviderAuthorization": { "type": "boolean", "description": "Opt-in pre-claim readiness predicate. When true, autonomous dispatch first performs a non-mutating check that the instance's resolved provider credential can read the gaggle repository and its issues. Invalid, revoked, insufficient, unsupported, or unverifiable credentials fail closed: no run starts and the scheduler reports a stable provider-auth-unhealthy reason. Manual runs stay available for diagnosis." }
          }
        },
        "runControls": { "$ref": "#/$defs/runControls", "description": "Workflow-level overrides for inherited runner safety budgets." },
        "backprop": {
          "type": "object",
          "description": "Explicitly enrolls terminal runs in provenance-aware Backprop attribution. Omitted, mode=off, or enabled=false without a mode performs no attribution work.",
          "additionalProperties": false,
          "required": ["version"],
          "anyOf": [{ "required": ["enabled"] }, { "required": ["mode"] }],
          "not": { "required": ["enabled", "mode"], "properties": { "enabled": { "const": true }, "mode": { "enum": ["off", "shadow"] } } },
          "properties": {
            "enabled": { "type": "boolean", "description": "Legacy enrollment switch: true means mode=active when mode is omitted." },
            "mode": { "enum": ["off", "shadow", "active"], "description": "Attribution mode. off performs no work; shadow does no work at run end and computes attribution on demand from the run journal for the shadow comparison report, which filing, gates, and default read surfaces never consume; active publishes the attribution record. Overrides enabled when set; enabled=true is accepted only with mode=active." },
            "version": { "const": "v1", "description": "Pinned Backprop attribution contract version." },
            "granularity": { "enum": ["run", "stage"], "description": "Preview. When attribution is recorded: run (default) writes only the end-of-run record; stage also writes a best-effort, read-only checkpoint after each stage finishes that the end-of-run record composes. A failed checkpoint never blocks a stage transition. Applies only to active mode: shadow runs write no stage checkpoints." }
          }
        },
        "outboxMirrorPath": { "type": "string", "minLength": 1, "description": "Absolute local filesystem root (or ~/ path) where durable journal outbox files are additionally mirrored. Tasks may override it." },
        "start": { "type": "string", "minLength": 1, "examples": ["act"], "description": "Name of the first task, gate, or parallel state." },
        "docsRoots": {
          "type": "array",
          "description": "In-repo documentation roots this workflow keeps current (docs-updater, #472/#1016). Ordered repo-relative paths (files or directories); the run's writes are confined to these roots. Each must be non-empty and must not escape the repository.",
          "items": { "type": "string", "minLength": 1 }
        },
        "tutorScope": {
          "type": "object",
          "description": "Declares this workflow as a Tutor-role definition and its topology tier (TUT-A4): per-workflow (confined to target's own subtree) or per-gaggle (the gaggle's shared config).",
          "additionalProperties": false,
          "required": ["tier"],
          "properties": {
            "tier": { "type": "string", "enum": ["per-workflow", "per-gaggle"], "description": "Tutor topology tier: confined to one workflow or shared across its gaggle." },
            "target": { "type": "string", "minLength": 1, "description": "Workflow name a per-workflow tutor is confined to. Omit for a per-gaggle tutor." }
          }
        },
        "requires": {
          "type": "object",
          "description": "Provider-capability requirements this workflow needs from its gaggle's connected provider (CONF-6, #2079). Distinct from a task's requiredCapabilities (runner/toolchain) and capabilities (credential grants). Omit to derive the requirement set from the stages this workflow uses; an explicit value here replaces that derivation entirely.",
          "additionalProperties": false,
          "properties": {
            "capabilities": {
              "type": "array",
              "description": "Provider capability keys this workflow requires (e.g. \"pr.merge\", \"pr.landing.enqueue\") — see docs/design/provider-contract-conformance.md §3.1.",
              "items": { "type": "string", "minLength": 1 }
            }
          }
        },
        "tasks": { "type": "array", "description": "Work states in the workflow state machine.", "items": { "$ref": "#/$defs/task" } },
        "gates": { "type": "array", "description": "Validation and branching states in the workflow state machine.", "items": { "$ref": "#/$defs/gate" } },
        "parallels": { "type": "array", "description": "Static fan-out/fan-in states in the workflow state machine.", "items": { "$ref": "#/$defs/parallel" } },
        "maps": { "type": "array", "maxItems": 128, "description": "DSL 3.1 preview data-driven fan-out states. Each runs one declared task once per entry of a frozen roster document. Runtimes refuse maps at run start until they implement them.", "items": { "$ref": "#/$defs/map" } }
      }
    }
  },
  "allOf": [
    {
      "if": {
        "not": {
          "properties": { "dslVersion": { "const": "3.1" } },
          "required": ["dslVersion"]
        }
      },
      "then": {
        "properties": {
          "spec": {
            "properties": {
              "tasks": {
                "items": {
                  "not": {
                    "anyOf": [
                      { "required": ["artifactSlots"] },
                      { "required": ["artifactInputs"] },
                      { "required": ["childWorkflows"] }
                    ]
                  }
                }
              },
              "parallels": {
                "items": {
                  "not": { "required": ["selection"] },
                  "properties": {
                    "branches": { "items": { "not": { "required": ["optional"] } } }
                  }
                }
              }
            },
            "not": { "required": ["maps"] }
          }
        }
      }
    }
  ],
  "$defs": {
    "branch": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "start"],
      "properties": {
        "name": { "type": "string", "minLength": 1, "description": "Branch identifier used in journal events, completeness records, and branch-qualified input references." },
        "start": { "type": "string", "minLength": 1, "description": "Name of this branch's first task or gate." },
        "optional": { "type": "boolean", "description": "DSL 3.1 preview. When true, the branch runs only when the parallel's frozen selection names it; requires the parallel to declare selection. Non-optional branches always run." }
      }
    },
    "fanOutSource": {
      "type": "object",
      "additionalProperties": false,
      "required": ["task", "slot"],
      "properties": {
        "task": { "type": "string", "minLength": 1, "description": "Task that publishes the source document. It must run before the fan-out on every path." },
        "slot": { "type": "string", "pattern": "^[A-Za-z0-9_-]{1,128}$", "description": "Name of an application/json artifactSlots entry on the source task." }
      }
    },
    "map": {
      "description": "DSL 3.1 preview data-driven fan-out state: runs one declared task once per entry of a frozen roster document (api/schemas/fanout-roster.schema.json), through the static parallel executor, then runs join once. failurePolicy, join and onFailure keep static parallel semantics.",
      "type": "object",
