    "description": "Instance-wide Temporal payload encryption. A keyRef enables the shared codec on every client and memo reader; absent keyRef preserves the SDK default and plaintext payload bytes.",
    "type": "object", "additionalProperties": false,
    "properties": {
      "payloadCodec": {
        "description": "Opt-in sealed payload codec library. An absent keyRef keeps the default converter when explicitly constructed.",
        "type": "object", "additionalProperties": false,
        "properties": {
