const fs = require('node:fs');
const { execFileSync } = require('node:child_process');
const report = JSON.parse(fs.readFileSync('.goobers/authoring-report.json', 'utf8'));
const result = JSON.parse(fs.readFileSync('.goobers/result.json', 'utf8'));
const scalar = value => value === null || ['string', 'number', 'boolean'].includes(typeof value);
const assertions = [
  ['status', ['ready', 'unresolved'].includes(report.status)],
  ['loadedPaths', Array.isArray(report.contract.loadedPaths) && report.contract.loadedPaths.every(x => typeof x === 'string')],
  ['skillSHA256', typeof report.contract.skillSHA256 === 'string'],
  ['terms', report.terms && !Array.isArray(report.terms) && Object.values(report.terms).every(x => typeof x === 'string')],
  ['command', typeof report.command === 'string' || (Array.isArray(report.command) && report.command.every(x => typeof x === 'string'))],
  ['evidence', Array.isArray(report.evidence) && report.evidence.every(x => typeof x.conclusion === 'string' && typeof x.citation === 'string')],
  ['proposal', typeof report.proposal.stateGraph === 'string' && Array.isArray(report.proposal.paths) && typeof report.proposal.presentedBeforeWrite === 'boolean' && Array.isArray(report.proposal.capabilities) && report.proposal.capabilities.every(x => typeof x.name === 'string' && typeof x.reason === 'string') && Array.isArray(report.proposal.omittedCapabilities)],
  ['release', Object.values(report.release).every(x => typeof x === 'string')],
  ['validation', typeof report.validation.command === 'string' && typeof report.validation.status === 'string' && Array.isArray(report.validation.attempts) && report.validation.attempts.every(x => typeof x.status === 'string' && typeof x.finding === 'string')],
  ['diff', typeof report.diff === 'string' && report.diff === execFileSync('git', ['diff', '--no-ext-diff'], {encoding:'utf8'})],
  ['unresolved', Array.isArray(report.unresolved) && report.unresolved.every(x => typeof x === 'string')],
  ['result', result.status === 'success' && Object.values(result.outputs).every(scalar) && !('error' in result)],
];
const failed = assertions.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) throw new Error(`report checks failed: ${failed.join(', ')}`);
console.log('reports valid; diff bytes=' + Buffer.byteLength(report.diff));
