"repo": {
  "description": "One target repository and the identity this instance reaches it with. GitHub and Gitea are two-part (owner/name); Azure DevOps is THREE-part (organization/project/repository) — owner carries the organization and project carries the middle segment.",
  "type": "object",
  "additionalProperties": false,
  "required": ["provider", "owner", "name"],
  "properties": {
    "provider": {
      "type": "string",
      "enum": ["github", "ado", "gitea"],
      "description": "Backing system for this repository. It selects both the API surface and which auth kinds are accepted."
    },
    "baseUrl": {
      "type": "string",
      "format": "uri",
      "description": "Forge root URL (e.g. https://gitea.example.com). Required for provider `gitea`, which has no fixed host; omitted for ado. Rejected for provider `github`: GitHub Enterprise Server is unsupported, so a github repository always means github.com."
    },
    "owner": {
      "type": "string",
      "minLength": 1,
      "description": "GitHub organization or user, Gitea owner, or Azure DevOps ORGANIZATION (the first segment of dev.azure.com/<organization>)."
    },
    "project": {
      "type": "string",
      "minLength": 1,
      "description": "Azure DevOps PROJECT — the middle segment of the three-part organization/project/repository identity. Required for provider `ado`; rejected for github and gitea, where it has no meaning."
    },
    "name": { "type": "string", "minLength": 1, "description": "Repository name — the last segment of the identity." },
    "token": {
      "description": "Where this repository's credential is read from. Required for PAT auth and externally minted github-app-token auth. It must be ABSENT for an auth kind that mints or borrows an identity (github-app, azure-cli, workload-identity, managed-identity): exactly one identity mechanism per repository, since a token alongside a minted one could only act as a silent fallback.",
      "$ref": "#/$defs/tokenRef"
    },
    "auth": {
      "description": "Non-default credential source for this repository. Omitted means PAT auth with token configured — byte-identical to an instance that predates this block.",
      "$ref": "#/$defs/repoAuth"
    },
    "policy": {
      "description": "This repository's declared forge-conformance manifest: the live settings `goobers doctor --repo` diffs against. GitHub-only. Omitted declares no expectation and changes nothing.",
      "$ref": "#/$defs/repoPolicy"
    },
    "largeRepo": {
      "$ref": "instance-repository-execution.schema.json#/properties/largeRepo",
      "description": "Enables the monolith-safe execution preset (pinned serial workspace, 4h stage timeout, path-length preflight, retention exemption, narrowed mirror refresh). The preset supplies DEFAULTS only — every explicit setting below overrides it."
    },
    "workspace": {
      "$ref": "instance-repository-execution.schema.json#/properties/workspace",
      "description": "How this repository is materialized for local runs. Pinned mode is deliberately non-hermetic: ignored and untracked build state may persist between runs, so the repository's .gitignore hygiene becomes load-bearing for clean run-branch diffs."
    },
    "pathLength": {
      "$ref": "instance-repository-execution.schema.json#/properties/pathLength",
      "description": "Checkout path-length preflight for this repository. Declaring the block enables it on every host, not just Windows; set disabled to opt out."
    },
