{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://goobers.dev/schemas/instance.schema.json",
  "title": "Instance",
  "description": "instance.yaml — the deployment-owned provisioning file `goobers init` writes first and the first file an operator edits. It declares which repositories this instance connects to, WHERE each credential is read from (never the value itself, CFG-009/SEC-010), and the instance-wide runner claims, run conditions, and telemetry every gaggle inherits. Gaggle/goober/workflow definitions are config-as-code reconciled from the workflow source; this file is provisioning, so it is loaded strictly — an unknown field is an error, never a silently ignored setting.",
  "type": "object",
  "additionalProperties": false,
  "required": ["apiVersion", "kind", "repos"],
  "allOf": [
    {
      "$comment": "The other half of the strict-load contract (#4217): a runners: inventory is schema revision 2, so declaring one without saying so is refused here exactly as the loader refuses it. Without this, editor validation would accept a file the daemon rejects.",
      "if": { "required": ["runners"] },
      "then": {
        "required": ["schemaVersion"],
        "properties": { "schemaVersion": { "const": 2 } }
      }
    }
  ],
  "properties": {
    "placement": {
      "type": "object",
      "additionalProperties": false,
      "description": "Instance workflow placement policy. Omitted keeps local execution compatible; hosted instances should explicitly deny self execution.",
      "properties": {
        "selfExecution": { "type": "string", "enum": ["allow", "deny"], "default": "allow", "description": "allow permits local workflow work (the default); deny refuses every self placement, including agentic reviewer gates." }
      }
    },
    "cost": {
      "type": "object",
      "description": "Instance default for external cost publication; local usage accounting remains active.",
      "additionalProperties": false,
      "properties": {
        "enabled": {
          "type": ["boolean", "null"],
          "description": "Enables provider-visible cost receipts and summaries by default. Omitted or null means true; a gaggle may override this setting."
        }
      }
    },
    "apiVersion": { "const": "goobers.dev/v1alpha1", "description": "API version of this instance file." },
    "kind": { "const": "Instance", "description": "Definition kind; always Instance." },
    "schemaVersion": {
      "description": "Instance-config schema revision — this file's first version field. Absent means 1, the pre-Goobernetes schema every existing install is on; 2 introduces the runners: inventory. Loading is strict on BOTH halves of the contract: declaring runners: REQUIRES schemaVersion 2 (the loader refuses the pair otherwise, #4217), so a runners:-bearing config hard-fails on an older binary by design instead of loading there and silently dropping the whole inventory. `goobers fix --instance-schema` adds the line.",
      "type": "integer",
      "enum": [1, 2]
    },
    "repos": {
      "description": "Repositories this instance connects to. Every gaggle's project and backlog must resolve to an entry here — a gaggle whose provider/owner/name matches no entry has no credential and can never run — so this list, not the gaggle, is where a repository's identity and auth live.",
      "type": "array",
      "items": { "$ref": "#/$defs/repo" }
    },
    "selfIdentity": {
      "type": "string",
      "minLength": 1,
      "description": "Provider login this instance acts as, used for assignment-aware backlog selection. An identity value, never a credential. A gaggle's own spec.selfIdentity overrides it; empty leaves assignment-aware selection opted out."
    },
    "needsHumanAssignee": {
      "type": "string",
      "minLength": 1,
      "description": "Provider identity work items are assigned to when Goobers parks them for human attention. Empty leaves parked items unassigned, so nobody is notified."
    },
    "credentials": {
      "description": "Per-capability and per-MCP credential sources. A capability entry overrides the repo-token default for that one capability (e.g. a separate review identity, since an author cannot approve its own pull request); an MCP entry is reachable only through a goober's explicit MCP server reference. Agentic stages fall back to the current user's stored harness sign-in when no agent:model entry is configured, which is why a headless service account needs one.",
      "type": "array",
      "items": { "$ref": "#/$defs/credentialGrant" }
    },
    "daemonIdentity": {
      "description": "Distinct bot identity for the daemon's own authored pull requests, reviews, merges, CI cancellation, and comments (UNOP-7). Omitted keeps every mutation on the repository token. Configuring it backs the standard daemon-mutation capability set (repo:push, github:issues:write, github:pr:write, github:pr:review, provider:ci:cancel, github:branch:delete, github:pr:merge) without declaring each one under credentials; an explicit credentials entry for one of those still wins.",
      "$ref": "#/$defs/daemonIdentity"
    },
    "secretStores": {
      "description": "Named external secret stores a token ref may resolve through (SEC-010). A store declares WHERE a secret lives, never a value; any token ref then opts in with `store: <storeName>/<secretName>` instead of env/file. Authentication to the store itself always uses an ambient identity — never a token ref, which would be circular. An instance that declares no stores and uses only env/file refs behaves exactly as it did before this field existed.",
      "type": "array",
      "items": { "$ref": "#/$defs/secretStore" }
    },
    "workflowSource": {
      "description": "Where the definitions-as-code tree (gaggles, goobers, workflows) is read from, independently of the target code repositories. Omitted keeps the local <instance-root>/config directory.",
      "$ref": "#/$defs/workflowSource"
    },
    "configMirrorPath": {
      "type": "string",
      "description": "Absolute shared path where the daemon publishes worker-consumable rendered configuration after successful synchronization or reload. Omitted or empty disables the mirror. Workers seed their local instance configuration without fetching the configuration repository or receiving its credentials."
    },
    "runner": {
      "description": "This runner's static claims and execution defaults: the toolchains it advertises, the extra ambient environment variables stages may see, and the baseline stage deadline.",
      "$ref": "#/$defs/runner"
    },
    "runners": {
      "description": "The runner inventory (plural; supersedes the singular runner block's capability claims). Each entry is one runner class the scheduler may place stages on: the daemon host itself (host: self), a container image the dispatcher instantiates one fresh, never-reused pod per stage attempt from, or a consumer-authored Deployment named as a pod template by reference. Absent, the singular runner block maps to the implicit self entry — the zero-change upgrade every existing install rides. Declared, runner.capabilities must be empty: the inventory owns capability claims (the runner block's execution settings keep their current homes). Inventory edits are restart-only in v1; in-flight runs finish against their pinned snapshot (accept-and-pin).",
      "type": "array",
      "items": { "$ref": "#/$defs/runnerEntry" }
    },
    "isolation": {
      "description": "Operator-owned, strengthen-only isolation floor. Matching mandates are unioned with stage requirements; no runner is granted effects by a mandate. An unsatisfiable floor fails validation. Omitted preserves existing placements; changes require restart.",
      "type": "object",
      "additionalProperties": false,
      "required": ["mandates"],
      "properties": {
        "mandates": {
          "description": "Restrictions required of every stage in the selected class. Multiple matching entries are unioned.",
          "type": "array",
          "minItems": 1,
          "items": {
            "description": "One class-scoped operator mandate.",
            "type": "object",
            "additionalProperties": false,
            "required": ["match", "restrictions"],
            "properties": {
              "match": {
                "description": "The stage class this mandate covers.",
                "type": "object",
                "additionalProperties": false,
                "required": ["stageClass"],
                "properties": {
                  "stageClass": {
                    "description": "Agentic tasks/reviewers or deterministic tasks/control-plane gates.",
                    "type": "string",
                    "enum": ["agentic", "deterministic"]
                  }
                }
              },
              "restrictions": {
                "description": "Required enforced effects from the same closed list as runner restrictions.",
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {
                  "description": "One required isolation effect.",
                  "type": "string",
                  "enum": ["network:none", "network:allowlist", "fs:readonly-except-workspace", "tmp:ephemeral", "env:default-deny"]
                }
              }
            }
          }
        }
      }
    },
    "egress": {
      "description": "Operator-supplied network destination set the per-runner-class NetworkPolicy renderer (`goobers netpol-render`, issue #3568) fills into the rendered reference manifests. Omitted renders nothing and changes nothing about local execution — the daemon never applies cluster networking; it renders, and the cluster operator applies.",
      "$ref": "#/$defs/egress"
    },
    "engine": {
      "description": "Tier-3 Temporal engine connection shared by the runtime, scheduler, workers, dispatchers, and daemon projection loop. GOOBERS_TEMPORAL_HOSTPORT, GOOBERS_TEMPORAL_NAMESPACE, and GOOBERS_TASK_QUEUE override these values at process startup.",
      "$ref": "#/$defs/engine"
    },
    "runConditions": {
      "description": "Instance-wide ceilings on top of each workflow's own readiness block. They only ever narrow what a workflow already permits.",
      "$ref": "#/$defs/runConditions"
    },
    "telemetry": {
      "description": "Local telemetry rollup store, optional collector push, and journal/rollup retention.",
      "$ref": "#/$defs/telemetry"
    },
    "externalTelemetry": {
      "description": "Named, read-only operational telemetry connectors workflows may query. A workflow selects only a connector name and generic query inputs, so provider-specific fields stay confined to this section.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "connectors": {
          "description": "Connector instances available to workflows, addressed by name. Names are unique within the instance.",
          "type": "array",
          "items": { "$ref": "#/$defs/externalTelemetryConnector" }
        }
      }
    },
    "retention": {
